1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.util.ArrayList;
4	import java.util.List;
5	
6	import jakarta.validation.Valid;
7	import net.officefloor.plugin.variable.Out;
8	import org.springframework.samples.petclinic.mapper.OwnerMapper;
9	import org.springframework.samples.petclinic.model.Owner;
10	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
11	import org.springframework.samples.petclinic.rest.escalation.InvalidTelephoneException;
12	import org.springframework.samples.petclinic.rest.escalation.MissingOwnerFieldsException;
13	import org.springframework.validation.annotation.Validated;
14	import org.springframework.web.bind.annotation.RequestBody;
15	
16	@Validated
17	public class BuildOwner {
18	
19	    public void service(@Valid @RequestBody OwnerFieldsDto request, OwnerMapper ownerMapper, Out<Owner> built)
20	            throws MissingOwnerFieldsException, InvalidTelephoneException {
21	        List<String> missing = new ArrayList<>();
22	        if (isBlank(request.getFirstName())) {
23	            missing.add("firstName");
24	        }
25	        if (isBlank(request.getLastName())) {
26	            missing.add("lastName");
27	        }
28	        if (isBlank(request.getAddress())) {
29	            missing.add("address");
30	        }
31	        if (isBlank(request.getCity())) {
32	            missing.add("city");
33	        }
34	        if (isBlank(request.getTelephone())) {
35	            missing.add("telephone");
36	        }
37	        if (!missing.isEmpty()) {
38	            throw new MissingOwnerFieldsException(missing);
39	        }
40	        // Normalize the telephone: strip every non-digit, then require exactly 10 digits.
41	        String telephone = request.getTelephone().replaceAll("\\D", "");
42	        if (telephone.length() != 10) {
43	            throw new InvalidTelephoneException(
44	                    "Telephone must be exactly 10 digits after removing non-digit characters");
45	        }
46	        request.setTelephone(telephone);
47	        built.set(ownerMapper.toOwner(request));
48	    }
49	
50	    private static boolean isBlank(String value) {
51	        return value == null || value.isBlank();
52	    }
53	}
