The pipeline is a 3-step OfficeFloor chain: `BuildOwner` → `SaveOwner` → `RespondWithOwnerCreated`, all governed by a `transaction`, and requires role `OWNER_ADMIN`.

## 2. Java function classes in the POST pipeline

**`/home/daniel/sandbox/src/main/java/org/springframework/samples/petclinic/rest/function/owner/BuildOwner.java`** — validates required fields, then normalizes telephone by stripping non-digits and requires exactly 10 digits (throws `InvalidTelephoneException`), then maps via `OwnerMapper.toOwner(OwnerFieldsDto)`.
```java
package org.springframework.samples.petclinic.rest.function.owner;

import java.util.ArrayList;
import java.util.List;

import jakarta.validation.Valid;
import net.officefloor.plugin.variable.Out;
import org.springframework.samples.petclinic.mapper.OwnerMapper;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
import org.springframework.samples.petclinic.rest.escalation.InvalidTelephoneException;
import org.springframework.samples.petclinic.rest.escalation.MissingOwnerFieldsException;
import org.springframework.validation.annotation.Validated;
import org.springframework.web.bind.annotation.RequestBody;

@Validated
public class BuildOwner {

    public void service(@Valid @RequestBody OwnerFieldsDto request, OwnerMapper ownerMapper, Out<Owner> built)
            throws MissingOwnerFieldsException, InvalidTelephoneException {
        List<String> missing = new ArrayList<>();
        if (isBlank(request.getFirstName())) {
            missing.add("firstName");
        }
        if (isBlank(request.getLastName())) {
            missing.add("lastName");
        }
        if (isBlank(request.getAddress())) {
            missing.add("address");
        }
        if (isBlank(request.getCity())) {
            missing.add("city");
        }
        if (isBlank(request.getTelephone())) {
            missing.add("telephone");
        }
        if (!missing.isEmpty()) {
            throw new MissingOwnerFieldsException(missing);
        }
        // Normalize the telephone: strip every non-digit, then require exactly 10 digits.
        String telephone = request.getTelephone().replaceAll("\\D", "");
        if (telephone.length() != 10) {
            throw new InvalidTelephoneException(
                    "Telephone must be exactly 10 digits after removing non-digit characters");
        }
        request.setTelephone(telephone);
        built.set(ownerMapper.toOwner(request));
    }

    private static boolean isBlank(String value) {
        return value == null || value.isBlank();
    }
}
